void sl_cmdline_help(void)
{
	fputs("Usage: schedlab [OPTIONS]\n", stdout);
	fputs("Show how thread scheduling behaves on Linux, PREEMPT_RT and QNX\n", stdout);
	fputs("\nOptions:\n", stdout);
	fputs("\n  Test setup:\n", stdout);
	fputs("      --scenario             ENUM     Scenario to run: s1 s2 s3 s4 s4net s5 sender.\n", stdout);
	fputs("      --cpu                  UINT32   Core that all test threads are pinned to.  [default: 1]\n", stdout);
	fputs("      --duration             TIME     Test length, for example 10s. (units: s|ms)  [default: 10s]\n", stdout);
	fputs("      --csv                  PATH     Write results to this CSV file.\n", stdout);
	fputs("      --quiet                         Print only the final result.\n", stdout);
	fputs("\n  Scheduling:\n", stdout);
	fputs("      --policy               ENUM     Scheduling policy of the test threads.  [default: fifo]\n", stdout);
	fputs("      --prio                 UINT32   Priority of the test threads (fifo, rr).  [default: 50]\n", stdout);
	fputs("      --nice                 INT32    Nice value (policy other). Write --nice=-5 for negatives.  [default: 0]\n", stdout);
	fputs("      --yield-every          UINT32   Hog calls sched_yield() every N iterations (0 = never).  [default: 0]\n", stdout);
	fputs("\n  Priorities per role:\n", stdout);
	fputs("      --hog-prio             UINT32   FIFO priority of the hog thread.  [default: 70]\n", stdout);
	fputs("      --producer-prio        UINT32   FIFO priority of the producer thread (s4).  [default: 50]\n", stdout);
	fputs("      --consumer-prio        UINT32   FIFO priority of the consumer thread (s4, s4net).  [default: 90]\n", stdout);
	fputs("\n  Timing and network:\n", stdout);
	fputs("      --period               TIME     Period of the periodic thread, for example 1ms. (units: us|ms)  [default: 1ms]\n", stdout);
	fputs("      --port                 UINT32   UDP port (s4net, sender).  [default: 5000]\n", stdout);
	fputs("      --target               STRING   Receiver IP address (sender).\n", stdout);
	fputs("      --rate                 FREQ     Packets per second (sender), for example 1kHz. (units: Hz|kHz)  [default: 1kHz]\n", stdout);
	fputs("\n", stdout);
	fputs("      --help                          Show this help\n", stdout);
	fputs("      --version                       Show version\n", stdout);
}

void sl_cmdline_version(void)
{
	fprintf(stdout, "%s\n", sl__version);
}

void sl_cmdline_dump(const struct sl_cmdline *args)
{
	(void)args;
	fprintf(stdout, "scenario=%ld\n", (long)args->scenario);
	fprintf(stdout, "cpu=%ld\n", (long)args->cpu);
	fprintf(stdout, "duration=%lu ns\n", (unsigned long)sl_duration_to_ns(&args->duration));
	fprintf(stdout, "csv=%s\n", args->csv);
	fprintf(stdout, "quiet=%d\n", args->quiet);
	fprintf(stdout, "policy=%ld\n", (long)args->policy);
	fprintf(stdout, "prio=%ld\n", (long)args->prio);
	fprintf(stdout, "nice=%ld\n", (long)args->nice);
	fprintf(stdout, "yield-every=%ld\n", (long)args->yield_every);
	fprintf(stdout, "hog-prio=%ld\n", (long)args->hog_prio);
	fprintf(stdout, "producer-prio=%ld\n", (long)args->producer_prio);
	fprintf(stdout, "consumer-prio=%ld\n", (long)args->consumer_prio);
	fprintf(stdout, "period=%lu ns\n", (unsigned long)sl_duration_to_ns(&args->period));
	fprintf(stdout, "port=%ld\n", (long)args->port);
	fprintf(stdout, "target=%s\n", args->target);
	fprintf(stdout, "rate=%lu hz\n", (unsigned long)sl_frequency_to_hz(&args->rate));
}
